// en.yaml rule en.subjectAgreement def AS_PARTITIVE
export const AS_PARTITIVE =
  /^(?:part|parts|portion|percentage|percent|fraction|proportion|share|half|bulk|kind|kinds|sort|sorts|type|types|amount|plenty|lots|dozens|hundreds|thousands|millions|one|none)$/;

// en.yaml rule en.subjectAgreement def AS_AUXILIARY_FORMS
export const AS_AUXILIARY_FORMS =
  /^(?:do|does|did|don't|doesn't|didn't|can|could|will|would|should|must|may|might|shall|can't|couldn't|won't|wouldn't|shouldn't|is|are|was|were|isn't|aren't|wasn't|weren't|has|have|had|hasn't|haven't|hadn't)$/;

// en.yaml rule en.subjectAgreement def AS_SINGULAR_FORMS
export const AS_SINGULAR_FORMS = /^(?:is|was|has|does|isn't|wasn't|hasn't|doesn't)$/;

// en.yaml rule en.subjectAgreement def AS_PLURAL_FORMS
export const AS_PLURAL_FORMS = /^(?:are|were|have|do|aren't|weren't|haven't|don't)$/;

// en.yaml rule en.subjectAgreement def AS_BLANK
export const AS_BLANK = /[ \t ]/;

// en.yaml rule en.subjectAgreement def asNormal
export function asNormal(word: string) {
  const lower = word.toLowerCase();
  return lower.includes("’") ? lower.replaceAll("’", "'") : lower;
}

// en.yaml rule en.subjectAgreement def asPluralOf
export function asPluralOf(
  token: EnToken,
  nextToken: EnToken | undefined,
  afterNext: EnToken | undefined,
) {
  const word = asNormal(token.lower);
  return AS_TO_PLURAL[word] || asPluralVerb(word, nextToken, afterNext);
}

// en.yaml rule en.subjectAgreement def asPluralVerb
export function asPluralVerb(
  word: string,
  nextToken: EnToken | undefined,
  afterNext: EnToken | undefined,
) {
  if (!(/s$/.test(word) && !EN_FUNCTION_WORDS.has(word))) return null;
  const read = englishWordInfo(word);
  if (!read?.verbs.some((v) => v.form === "third")) return null;
  if (!(!(read.noun || read.plural) || asClosedVerb(word, nextToken, afterNext))) return null;
  return englishLemma(word, "third");
}

// en.yaml rule en.subjectAgreement def asClosedVerb
export function asClosedVerb(
  word: string,
  nextToken: EnToken | undefined,
  afterNext: EnToken | undefined,
) {
  const next = nextToken?.kind === "word" ? englishWordInfo(nextToken.lower) : null;
  const verbAfter =
    afterNext?.kind === "word" &&
    !!englishWordInfo(afterNext.lower)?.verbs.some((v) => v.form === "past" || v.form === "third");
  const adverbNext =
    nextToken?.kind === "word" &&
    !verbAfter &&
    (EN_ADVERBS.has(nextToken.lower) ||
      /^(?:late|early|fast|hard|well|today|tonight|loudly|everywhere|together)$/.test(
        nextToken.lower,
      ) ||
      (!!next?.adverb && !next.noun));
  const linked =
    /^(?:sounds|seems|looks|feels|tastes|smells|appears)$/.test(word) &&
    !!next?.adjective &&
    !next.verbs.length;
  return (
    !nextToken ||
    nextToken.kind === "end" ||
    adverbNext ||
    linked ||
    (nextToken.kind === "word" &&
      /^(?:the|a|an|my|your|his|her|our|their|it|them|me|us|him|you|that|to|in|on|at|with|for|every|each)$/.test(
        nextToken.lower,
      ))
  );
}

// en.yaml rule en.subjectAgreement def asPush
export function asPush(ctx: DetectContext, token: EnToken, replacement: string, from: number) {
  return finding(
    "englishSubjectVerbAgreement",
    "review_msg_subject_verb",
    token.start,
    token.end,
    [caseLike(token.text, replacement)],
    { context: enEvidence(ctx, from, token.end) },
  );
}

// en.yaml rule en.subjectAgreement def asVerbNext
export function asVerbNext(tokens: EnToken[], at: number) {
  return (
    asVerbish(tokens[at]) || (EN_ADVERBS.has(tokens[at]?.lower ?? "") && asVerbish(tokens[at + 1]))
  );
}

// en.yaml rule en.subjectAgreement def asVerbish
export function asVerbish(t: EnToken | undefined) {
  return (
    asVerbOnlyThird(t) ||
    /^(?:looks|seems|sounds|feels|tastes|smells|appears)$/.test(t?.lower ?? "")
  );
}

// en.yaml rule en.subjectAgreement def asAuxLater
export function asAuxLater(tokens: EnToken[], i: number, object: boolean): boolean {
  const t = tokens[i];
  if (!(
    i < tokens.length &&
    t.kind === "word" &&
    !(object && /^(?:that|which|who|whom|whose|because|if|and|but|so)$/.test(t.lower))
  ))
    return false;
  return (
    /^(?:is|are|was|were|has|have|had|will|would|can|could|should|must|may|might)$/.test(t.lower) ||
    asAuxLater(
      tokens,
      i + 1,
      object || /^(?:the|a|an|my|your|his|her|our|their|its)$/.test(t.lower),
    )
  );
}

// en.yaml rule en.subjectAgreement def asVerbOnlyThird
export function asVerbOnlyThird(token: EnToken | undefined) {
  if (!(token?.kind === "word")) return false;
  const word = asNormal(token.lower);
  return !!AS_TO_PLURAL[word] || asThirdOnly(word);
}

// en.yaml rule en.subjectAgreement def asThirdOnly
export function asThirdOnly(word: string) {
  const read = englishWordInfo(word);
  return !!read?.verbs.some((v) => v.form === "third") && !read.noun && !read.plural;
}

// en.yaml rule en.subjectAgreement def asHeadNumber
export function asHeadNumber(word: string, bare: boolean) {
  return (
    enNounNumber(word) ??
    (EN_MASS.has(word) && !bare && !/^(?:livestock|poultry|wildlife|plankton)$/.test(word)
      ? { singular: word, plural: word, number: "singular" as const }
      : null)
  );
}

// en.yaml rule en.subjectAgreement def asBaseBeforeObject
export function asBaseBeforeObject(ctx: DetectContext, verb: EnToken, next: EnToken | undefined) {
  return verb.lower === "need"
    ? next?.kind === "word" &&
        (next.lower === "to" || (/ing$/.test(next.lower) && !EN_FUNCTION_WORDS.has(next.lower)))
    : asVerbBeforeObject(ctx, verb.lower, next);
}

// en.yaml rule en.subjectAgreement def asVerbBeforeObject
export function asVerbBeforeObject(ctx: DetectContext, word: string, next: EnToken | undefined) {
  if (EN_FUNCTION_WORDS.has(word) || /s$|^(?:please|thank|beware|better|best)$/.test(word))
    return false;
  const read = englishWordInfo(word);
  const forms = englishVerbForms(word);
  if (
    !read?.verbs.some((v) => v.form === "base" && v.lemma === word) ||
    read.adjective ||
    read.plural ||
    (forms && (forms.past === word || forms.participle === word))
  )
    return false;
  if (!(next?.kind === "word" && AS_OBJECT_START.test(next.lower))) return false;
  const hit = enTokensAfter(ctx, next.end, 6).find(
    (t) =>
      t.kind !== "word" ||
      AS_OBJECT_END.test(t.lower) ||
      EN_AUXILIARIES.has(t.lower) ||
      asFiniteNoNoun(t.lower),
  );
  return !hit || hit.kind !== "word" || AS_OBJECT_END.test(hit.lower);
}

// en.yaml rule en.subjectAgreement def asFiniteNoNoun
export function asFiniteNoNoun(word: string) {
  const r = englishWordInfo(word);
  return !!r?.verbs.some((v) => v.form === "past" || v.form === "third") && !r.noun;
}

// en.yaml rule en.subjectAgreement def asBareVerbOnly
export function asBareVerbOnly(word: string) {
  if (EN_FUNCTION_WORDS.has(word) || /s$|^(?:please|thank|beware)$/.test(word)) return false;
  const read = englishWordInfo(word);
  const forms = englishVerbForms(word);
  return (
    !!read &&
    read.verbs.some((v) => v.form === "base" && v.lemma === word) &&
    read.verbs.every((v) => v.form === "base") &&
    !read.noun &&
    !read.adjective &&
    !read.adverb &&
    !enNounNumber(word) &&
    !(forms && (forms.past === word || forms.participle === word))
  );
}

// en.yaml rule en.subjectAgreement def asClosedAfter
export function asClosedAfter(t: EnToken | undefined) {
  return !t || t.kind === "end"
    ? true
    : t.kind !== "word"
      ? false
      : /^(?:the|a|an|my|your|his|her|our|their|it|them|me|us|him|you|this|that|to|in|on|at|with|for|up|down|out|off|through|into|again|every|each)$/.test(
          t.lower,
        ) ||
        EN_ADVERBS.has(t.lower) ||
        (/ly$/.test(t.lower) && !!englishWordInfo(t.lower)?.adverb);
}

// en.yaml rule en.subjectAgreement def asAt
export function asAt(ctx: DetectContext, m: RegExpExecArray, group: string): EnToken {
  const span = m.indices!.groups![group];
  const text = ctx.text.slice(span[0], span[1]);
  return { text, lower: text.toLowerCase(), start: span[0], end: span[1], kind: "word" };
}

// en.yaml rule en.subjectAgreement def asOpens
export function asOpens(ctx: DetectContext, m: RegExpExecArray) {
  return enAfterBreak(ctx, m.index) || AS_CLAUSE_CUE.test(enWordBefore(ctx, m.index));
}

// en.yaml rule en.subjectAgreement def asCommaBefore
export function asCommaBefore(text: string, index: number) {
  const i = skipBackWhile(text, index, AS_BLANK);
  return i < index && i > 0 && text[i - 1] === ",";
}

// en.yaml rule en.subjectAgreement def asModifier
export function asModifier(text: string, t: ClauseToken | undefined) {
  if (!t || EN_FUNCTION_WORDS.has(t.w) || text.slice(t.start, t.end) !== t.w) return false;
  const read = englishWordInfo(t.w);
  return (
    !!read &&
    (read.adjective || (read.noun && enNounNumber(t.w)?.number !== "plural")) &&
    !read.verbs.some((v) => v.form === "past" || v.form === "third")
  );
}

// en.yaml rule en.subjectAgreement def asClauseAdverb
export function asClauseAdverb(t: ClauseToken) {
  return EN_ADVERBS.has(t.w) ? t.w !== "all" : asLyOnlyAdverb(t.w);
}

// en.yaml rule en.subjectAgreement def asLyOnlyAdverb
export function asLyOnlyAdverb(word: string) {
  const read = englishWordInfo(word);
  return /ly$/.test(word) && !!read?.adverb && !read.noun && !read.adjective && !read.verbs.length;
}

// en.yaml rule en.subjectAgreement def asClauseNoun
export function asClauseNoun(text: string, t: ClauseToken) {
  if (EN_FUNCTION_WORDS.has(t.w)) return false;
  return text.slice(t.start, t.end) !== t.w
    ? /^\p{Lu}\p{Ll}+$/u.test(text.slice(t.start, t.end))
    : asNounWord(t.w);
}

// en.yaml rule en.subjectAgreement def asNounWord
export function asNounWord(word: string) {
  const read = englishWordInfo(word);
  return !!enNounNumber(word) || !!read?.noun || !!read?.plural;
}

// en.yaml rule en.subjectAgreement def asPostnominal
export function asPostnominal(t: ClauseToken | undefined) {
  const read = t && englishWordInfo(t.w);
  return (
    !!read &&
    read.verbs.some((v) => v.form === "participle") &&
    read.verbs.every((v) => v.form === "participle" || v.form === "past" || v.form === "base") &&
    !read.noun &&
    !read.plural
  );
}

// en.yaml rule en.subjectAgreement def asPrenominal
export function asPrenominal(
  text: string,
  tokens: readonly ClauseToken[],
  i: number,
  k: number,
): number {
  return k < i + 3 &&
    asModifier(text, tokens[k]) &&
    !!tokens[k + 1] &&
    asClauseNoun(text, tokens[k + 1])
    ? asPrenominal(text, tokens, i, k + 1)
    : k;
}

// en.yaml rule en.subjectAgreement def AS_ENGLISH_CLAUSE
export const AS_ENGLISH_CLAUSE = {
  determiners: EN_DETERMINERS,
  prepositions: AS_CLAUSE_PREPOSITIONS,
  quantifiers: AS_CLAUSE_QUANTIFIERS,
  numbers: AS_CLAUSE_NUMBERS,
  notHeads: EN_FUNCTION_WORDS,
  coordinators: AS_CLAUSE_COORDINATORS,
  joins: AS_CLAUSE_JOINS,
  pronouns: AS_CLAUSE_PRONOUNS,
  relatives: AS_CLAUSE_RELATIVES,
  clitics: AS_CLAUSE_CLITICS,
  isAdverb: (t: ClauseToken) => asClauseAdverb(t),
  isNoun: (text: string, t: ClauseToken) => asClauseNoun(text, t),
  nominal: () => false,
  postnominal: (t: ClauseToken | undefined) => asPostnominal(t),
  prenominal: (text: string, tokens: readonly ClauseToken[], i: number) =>
    asPrenominal(text, tokens, i, i),
  isFiniteVerb: (t: ClauseToken) =>
    AS_AUXILIARY_FORMS.test(t.w) ||
    !!englishWordInfo(t.w)?.verbs.some(
      (v) => v.form === "third" || v.form === "past" || v.form === "base",
    ),
} as ClauseProfile;

// en.yaml rule en.subjectAgreement def asShownNumber
export function asShownNumber(t: ClauseToken) {
  return AS_SINGULAR_FORMS.test(t.w)
    ? "singular"
    : AS_PLURAL_FORMS.test(t.w)
      ? "plural"
      : asThirdOnly(t.w)
        ? "singular"
        : null;
}

// en.yaml rule en.subjectAgreement def asTakesClause
export function asTakesClause(t: ClauseToken) {
  return !!englishWordInfo(t.w)?.verbs.some((v) => AS_CLAUSE_TAKING.test(v.lemma));
}

// en.yaml rule en.subjectAgreement def asAttaches
export function asAttaches(verb: ClauseToken, numbers: readonly (string | undefined)[]) {
  const shown = asShownNumber(verb);
  return (!shown || numbers.includes(shown)) && !asTakesClause(verb);
}

// en.yaml rule en.subjectAgreement def asRelativeVerb
export function asRelativeVerb(
  text: string,
  tokens: ClauseToken[],
  i: number,
  numbers: readonly (string | undefined)[],
) {
  const at = verbAfterRelative(AS_ENGLISH_CLAUSE, text, tokens, i, (verb: ClauseToken) =>
    asAttaches(verb, numbers),
  );
  return at < 0 ? asVerbAfterObjectRelative(text, tokens, i) : at;
}

// en.yaml rule en.subjectAgreement def asVerbAfterObjectRelative
export function asVerbAfterObjectRelative(text: string, tokens: ClauseToken[], i: number) {
  if (!AS_ENGLISH_CLAUSE.relatives.has(tokens[i]?.w ?? "")) return -1;
  const phrase = skipNounPhrase(AS_ENGLISH_CLAUSE, text, tokens, i + 1);
  const subjectEnd =
    phrase !== i + 1
      ? phrase
      : /^(?:i|you|he|she|we|they)$/.test(tokens[phrase]?.w ?? "")
        ? phrase + 1
        : -1;
  if (!(subjectEnd >= 0)) return -1;
  const k = asSkipAuxiliaries(tokens, asSkipClauseAdverbs(tokens, subjectEnd));
  const verb = tokens[k];
  if (!(verb && !AS_AUXILIARY_FORMS.test(verb.w) && !!englishWordInfo(verb.w)?.verbs.length))
    return -1;
  const end = asSkipClauseAdverbs(tokens, skipComplements(AS_ENGLISH_CLAUSE, text, tokens, k + 1));
  return tokens[end] && AS_ENGLISH_CLAUSE.isFiniteVerb(tokens[end]) ? end : -1;
}

// en.yaml rule en.subjectAgreement def asSkipClauseAdverbs
export function asSkipClauseAdverbs(tokens: ClauseToken[], k: number): number {
  return tokens[k] && AS_ENGLISH_CLAUSE.isAdverb(tokens[k])
    ? asSkipClauseAdverbs(tokens, k + 1)
    : k;
}

// en.yaml rule en.subjectAgreement def asSkipAuxiliaries
export function asSkipAuxiliaries(tokens: ClauseToken[], k: number): number {
  return tokens[k] && AS_AUXILIARY_FORMS.test(tokens[k].w)
    ? asSkipAuxiliaries(tokens, asSkipClauseAdverbs(tokens, k + 1))
    : k;
}

// en.yaml rule en.subjectAgreement def asDistantFix
export function asDistantFix(
  ctx: DetectContext,
  words: EnToken[],
  at: number,
  number: "singular" | "plural",
  from: number,
) {
  const verb = words[at];
  if (!verb || verb.text !== verb.lower || ctx.dictionary.has(verb.lower)) return null;
  const word = asNormal(verb.lower);
  return number === "plural"
    ? asDistantPlural(words, at, word)
    : asDistantSingular(ctx, words, at, word, from);
}

// en.yaml rule en.subjectAgreement def asDistantPlural
export function asDistantPlural(words: EnToken[], at: number, word: string) {
  const next = EN_ADVERBS.has(words[at + 1]?.lower ?? "") ? words[at + 2] : words[at + 1];
  if (/^(?:is|was)$/.test(word) && /^(?:a|an|one)$/.test(next?.lower ?? "")) return null;
  return asPluralOf(words[at], words[at + 1], words[at + 2]);
}

// en.yaml rule en.subjectAgreement def asDistantSingular
export function asDistantSingular(
  ctx: DetectContext,
  words: EnToken[],
  at: number,
  word: string,
  from: number,
) {
  return AS_TO_SINGULAR[word]
    ? word === "were" && AS_SUBJUNCTIVE.test(ctx.text.slice(Math.max(0, from - 64), from))
      ? null
      : AS_TO_SINGULAR[word]
    : AS_SINGULAR_DO_HAVE[word]
      ? AS_SINGULAR_DO_HAVE[word]
      : /^(?:that|lest)$/.test(enWordBefore(ctx, from))
        ? null
        : asBareVerbOnly(word) && asClosedAfter(words[at + 1])
          ? englishInflect(word, "third")
          : null;
}

// en.yaml rule en.subjectAgreement def asHeadScan
export function asHeadScan(
  ctx: DetectContext,
  tokens: EnToken[],
  bare: boolean,
  broke: boolean,
  i: number,
  head: string | null,
): { i: number; head: string | null; abort: boolean } {
  const t = tokens[i];
  return i < 4 &&
    t?.kind === "word" &&
    (t.text === t.lower || (bare && i === 0 && /^[A-Z][a-z]+$/.test(t.text) && broke))
    ? asHeadStep(ctx, tokens, bare, broke, i, head, t.lower)
    : { i, head, abort: false };
}

// en.yaml rule en.subjectAgreement def asHeadStep
export function asHeadStep(
  ctx: DetectContext,
  tokens: EnToken[],
  bare: boolean,
  broke: boolean,
  i: number,
  head: string | null,
  word: string,
): { i: number; head: string | null; abort: boolean } {
  return EN_FUNCTION_WORDS.has(word) ||
    AS_TO_PLURAL[asNormal(word)] ||
    AS_TO_SINGULAR[asNormal(word)] ||
    AS_SINGULAR_DO_HAVE[asNormal(word)]
    ? { i, head, abort: false }
    : AS_NUMBERS.test(word)
      ? { i, head, abort: true }
      : asHeadRead(ctx, tokens, bare, broke, i, head, word);
}

// en.yaml rule en.subjectAgreement def asHeadRead
export function asHeadRead(
  ctx: DetectContext,
  tokens: EnToken[],
  bare: boolean,
  broke: boolean,
  i: number,
  head: string | null,
  word: string,
): { i: number; head: string | null; abort: boolean } {
  const number = asHeadNumber(word, bare);
  const read = englishWordInfo(word);
  return head &&
    /s$/.test(word) &&
    read?.verbs.some((v) => v.form === "third") &&
    !(
      read.plural &&
      (asVerbNext(tokens, i + 1) ||
        (!!englishWordInfo(head)?.adjective && /s$/.test(tokens[i + 1]?.lower ?? "")))
    )
    ? { i, head, abort: false }
    : head && !number && asBareVerbOnly(word)
      ? { i, head, abort: false }
      : head && asBaseBeforeObject(ctx, tokens[i], tokens[i + 1])
        ? { i, head, abort: false }
        : head && (!number || read?.adjective)
          ? { i, head, abort: true }
          : head && /ing$/.test(word) && enNounNumber(head)?.number === "plural"
            ? { i, head, abort: true }
            : number
              ? asHeadScan(ctx, tokens, bare, broke, i + 1, word)
              : !read?.adjective &&
                  !(bare && i === 0 && !!read?.verbs.some((v) => v.form === "participle"))
                ? { i, head, abort: false }
                : asHeadScan(ctx, tokens, bare, broke, i + 1, head);
}

// en.yaml rule en.subjectAgreement def asPhraseObjectEnd
export function asPhraseObjectEnd(
  tokens: EnToken[],
  limit: number,
  object: number,
  j: number,
): number {
  return j < limit &&
    tokens[j]?.kind === "word" &&
    !/^(?:i|you|we|they|he|she|who|which|that)$/.test(tokens[j].lower) &&
    !AS_TO_PLURAL[asNormal(tokens[j].lower)] &&
    !AS_TO_SINGULAR[asNormal(tokens[j].lower)] &&
    !(
      j > object &&
      tokens[j].text === tokens[j].lower &&
      /s$/.test(tokens[j].lower) &&
      englishWordInfo(tokens[j].lower)?.verbs.some((v) => v.form === "third")
    )
    ? asPhraseObjectEnd(tokens, limit, object, j + 1)
    : j;
}

// en.yaml rule en.subjectAgreement def asNounPluralFix
export function asNounPluralFix(
  tokens: EnToken[],
  verbAt: number,
  i: number,
  det: string,
  verb: EnToken,
) {
  if (/^(?:this|that)$/.test(det) && verbAt === i) return null;
  const predicate = EN_ADVERBS.has(tokens[verbAt + 1]?.lower ?? "")
    ? tokens[verbAt + 2]
    : tokens[verbAt + 1];
  if (/^(?:is|was)$/.test(verb.lower) && /^(?:a|an|one)$/.test(predicate?.lower ?? "")) return null;
  return asPluralOf(verb, tokens[verbAt + 1], tokens[verbAt + 2]);
}

// en.yaml rule en.subjectAgreement def asNounSingularFix
export function asNounSingularFix(
  ctx: DetectContext,
  m: RegExpExecArray,
  tokens: EnToken[],
  verbAt: number,
  i: number,
  adverbGap: boolean,
  verb: EnToken,
  norm: string,
) {
  return (
    AS_TO_SINGULAR[norm] ||
    (verbAt === i &&
    !/^(?:that|lest)$/.test(enWordBefore(ctx, m.index)) &&
    !/^(?:i|you|we|they|he|she|it)$/.test(tokens[verbAt + 1]?.lower ?? "")
      ? AS_SINGULAR_DO_HAVE[norm]
      : null) ||
    ((verbAt === i || adverbGap) &&
    !/^(?:that|lest)$/.test(enWordBefore(ctx, m.index)) &&
    (asBareVerbOnly(verb.lower) || (adverbGap && asOnlyBase(verb.lower))) &&
    asClosedAfter(tokens[verbAt + 1])
      ? englishInflect(verb.lower, "third")
      : null) ||
    (verbAt === i &&
    !/^(?:that|lest)$/.test(enWordBefore(ctx, m.index)) &&
    asBaseBeforeObject(ctx, verb, tokens[verbAt + 1])
      ? englishInflect(verb.lower, "third")
      : null)
  );
}

// en.yaml rule en.subjectAgreement def asOnlyBase
export function asOnlyBase(word: string) {
  const read = englishWordInfo(word);
  return (
    !!read?.verbs.length &&
    read.verbs.every((v) => v.form === "base" && v.lemma === word) &&
    !read.adjective
  );
}

// en.yaml rule en.subjectAgreement def asNounSubject
export function asNounSubject(
  m: RegExpExecArray,
  ctx: DetectContext,
  bare: boolean,
): RawFinding | null {
  const before = enWordBefore(ctx, m.index);
  const broke = !before && enAfterBreak(ctx, m.index);
  const opens =
    (before ? AS_CLAUSE_CUE.test(before) : broke) ||
    /(?:^|\n)[ \t]*[-*•][ \t ]+$/.test(ctx.text.slice(Math.max(0, m.index - 8), m.index)) ||
    (asCommaBefore(ctx.text, m.index) &&
      AS_OPENING_PHRASE.test(ctx.text.slice(Math.max(0, m.index - 80), m.index)));
  const later =
    !bare &&
    (/,[ \t ]+$/.test(ctx.text.slice(Math.max(0, m.index - 4), m.index)) ||
      AS_LATER_CUE.test(before));
  if (!(opens || later)) return null;
  const pluralOnly = bare || !opens;
  const det = bare ? "" : m.groups!.target.toLowerCase();
  const tokens = enTokensAfter(ctx, bare ? m.index : m.index + m[0].length, 9);
  if (tokens.some((t) => t.kind === "other")) return null;
  const scan = asHeadScan(ctx, tokens, bare, broke, 0, null);
  const i = scan.i;
  const head = scan.head;
  if (!(head && !scan.abort && !englishWordInfo(head)?.adjective)) return null;
  if (bare && AS_QUANTITY_HEAD.test(head)) return null;
  if (tokens.slice(0, i).some((t) => AS_MENTION.test(t.lower))) return null;
  const phrase = /^(?:of|in|from|for|with|at|on|by|after|since|near|across|inside|outside)$/.test(
    tokens[i]?.lower ?? "",
  );
  if (
    phrase &&
    /^(?:first|last|least|most|all|once|large|general|fact|least|times|best|worst)$/.test(
      tokens[i + 1]?.lower ?? "",
    )
  )
    return null;
  const objectStart = /^(?:the|a|an|my|your|his|her|our|their)$/.test(tokens[i + 1]?.lower ?? "")
    ? i + 2
    : i + 1;
  const afterPhrase = phrase ? asPhraseObjectEnd(tokens, i + 4, objectStart, objectStart) : i;
  const adverbGap =
    afterPhrase === i &&
    /^(?:always|never|often|usually|sometimes|rarely|seldom|also|still|just|really|only|even|already|actually|generally|normally|typically|mostly|probably)$/.test(
      tokens[afterPhrase]?.lower ?? "",
    );
  const verbAt = adverbGap ? afterPhrase + 1 : afterPhrase;
  const verb = tokens[verbAt];
  if (!(verb?.kind === "word" && verb.text === verb.lower)) return null;
  if (
    det === "all" &&
    (/^(?:is|was)$/.test(verb.lower) || /^(?:is|was)$/.test(tokens[verbAt + 1]?.lower ?? ""))
  )
    return null;
  if (
    /^were$/.test(verb.lower) &&
    AS_SUBJUNCTIVE.test(ctx.text.slice(Math.max(0, m.index - 64), m.index))
  )
    return null;
  const norm = asNormal(verb.lower);
  if (
    !AS_TO_PLURAL[norm] &&
    !AS_TO_SINGULAR[norm] &&
    (asAuxLater(tokens, verbAt + 1, false) ||
      (tokens.slice(0, i).some((t) => AS_GROUP_ADJECTIVES.test(t.lower)) &&
        !!englishWordInfo(head)?.verbs.some((v) => v.form === "third")))
  )
    return null;
  const number = asHeadNumber(head, bare)!;
  if (EN_COLLECTIVE.has(head) || EN_COLLECTIVE.has(number.singular)) return null;
  if (bare && i === 1 && tokens[0].text !== tokens[0].lower && AS_TO_PLURAL[norm]) return null;
  if (AS_TO_PLURAL[norm] && enTokensAfter(ctx, verb.end, 5).some((t) => AS_MENTION.test(t.lower)))
    return null;
  const fix =
    number.number === "plural"
      ? asNounPluralFix(tokens, verbAt, i, det, verb)
      : !pluralOnly &&
          !/^(?:these|those|many|several|both|some|most)$/.test(det) &&
          !(
            det === "all" &&
            !englishWordInfo(head)?.verbs.some((v) => v.form !== "base") &&
            englishNounPair(head)
          )
        ? asNounSingularFix(ctx, m, tokens, verbAt, i, adverbGap, verb, norm)
        : null;
  if (!fix) return null;
  return asPush(ctx, verb, fix, m.index);
}

// en.yaml rule en.subjectAgreementRelative def asRelativeMain
export function asRelativeMain(
  ctx: DetectContext,
  m: RegExpExecArray,
  tokens: EnToken[],
  plural: boolean,
  j: number,
  clauseVerb: number,
): RawFinding | null {
  if (!(j < tokens.length)) return null;
  const t = tokens[j];
  if (t.kind !== "word" || (t.text !== t.lower && t.text !== "I")) return null;
  if (/^(?:and|but|or|because|if|when|which|who|that|while)$/.test(t.lower)) return null;
  const read = englishWordInfo(t.lower);
  const verb =
    AS_BE_OR_AUX.test(t.lower) || (!!read?.verbs.length && !EN_FUNCTION_WORDS.has(t.lower));
  return clauseVerb < 0
    ? asRelativeMain(ctx, m, tokens, plural, j + 1, verb ? j : -1)
    : asRelativeStep(ctx, m, tokens, plural, j, clauseVerb, verb);
}

// en.yaml rule en.subjectAgreementRelative def asRelativeStep
export function asRelativeStep(
  ctx: DetectContext,
  m: RegExpExecArray,
  tokens: EnToken[],
  plural: boolean,
  j: number,
  clauseVerb: number,
  verb: boolean,
): RawFinding | null {
  const t = tokens[j];
  const read = englishWordInfo(t.lower);
  const prev = tokens[j - 1];
  const prevRead = englishWordInfo(prev.lower);
  const adverbBefore =
    EN_ADVERBS.has(prev.lower) ||
    AS_TIME_WORDS.test(prev.lower) ||
    (!!prevRead?.adverb && !prevRead.noun && !prevRead.adjective && !prevRead.verbs.length);
  const afterClauseVerb = j - 1 === clauseVerb && !AS_CATENATIVE.test(prev.lower);
  return tokens
    .slice(clauseVerb, j)
    .some((w) => AS_CATENATIVE.test(w.lower) || /^(?:gonna|wanna|gotta)$/.test(w.lower))
    ? null
    : !adverbBefore && !afterClauseVerb
      ? verb
        ? null
        : asRelativeMain(ctx, m, tokens, plural, j + 1, clauseVerb)
      : !verb
        ? asRelativeMain(ctx, m, tokens, plural, j + 1, clauseVerb)
        : adverbBefore || (!read?.noun && !read?.adjective)
          ? asRelativeFix(ctx, m, tokens, plural, j, adverbBefore)
          : read?.noun
            ? asRelativeMain(ctx, m, tokens, plural, j + 1, clauseVerb)
            : null;
}

// en.yaml rule en.subjectAgreementRelative def asRelativeFix
export function asRelativeFix(
  ctx: DetectContext,
  m: RegExpExecArray,
  tokens: EnToken[],
  plural: boolean,
  j: number,
  adverbBefore: boolean,
) {
  const t = tokens[j];
  const read = englishWordInfo(t.lower);
  const fix = plural
    ? asPluralOf(t, tokens[j + 1], tokens[j + 2])
    : AS_SINGULAR_OF[t.lower]
      ? AS_SINGULAR_OF[t.lower]
      : read?.verbs.some((v) => v.form === "base" && v.lemma === t.lower) &&
          (adverbBefore || !read.adjective) &&
          (!read.noun || asClosedAfter(tokens[j + 1]))
        ? englishInflect(t.lower, "third")
        : null;
  if (!(fix && fix !== t.lower)) return null;
  return asPush(ctx, t, fix, m.index);
}

// en.yaml rule en.adjectiveForAdverb def adverbListedLy
export function adverbListedLy(word: string) {
  const ly = englishWordInfo(word);
  return !!ly && (ly.adverb || (!ly.noun && !ly.adjective && !ly.verbs.length));
}

// en.yaml rule en.adjectiveForAdverb def adverbOf
export function adverbOf(adjective: string): string | null {
  if (adjective.length < 4 || ADVERB_NOT_BASE.has(adjective) || EN_FUNCTION_WORDS.has(adjective))
    return null;
  const read = englishWordInfo(adjective);
  if (!(read?.adjective && !read.verbs.length && !read.adverb)) return null;
  return (
    [
      adjective.replace(/le$/, "ly"),
      adjective.replace(/ic$/, "ically"),
      adjective.replace(/y$/, "ily"),
      `${adjective}ly`,
    ].find((c) => c !== adjective && /ly$/.test(c) && adverbListedLy(c)) ?? null
  );
}

// en.yaml rule en.adjectiveForAdverb def adverbVerbAfter
export function adverbVerbAfter(
  word: string,
  kind: "base" | "participle" | "finite",
  after: EnToken | undefined,
  derived: boolean,
): boolean {
  const read = englishWordInfo(word);
  const nounEnds = !after || after.kind === "end" || after.kind === "comma";
  const objectNext =
    (derived || kind === "finite") &&
    after?.kind === "word" &&
    /^(?:the|a|an|my|your|his|her|our|their|this|these|those|it|them|him|us|me|you|all|some|any|out|up|down|off|away|back)$/.test(
      after.lower,
    );
  return !read || EN_FUNCTION_WORDS.has(word)
    ? kind === "finite"
      ? /^(?:has|does|had|did|should|would|could|can|will|must|might|may)$/.test(word)
      : /^(?:be|have|do|not)$/.test(word)
    : kind === "base"
      ? (!read.noun || nounEnds || objectNext) &&
        read.verbs.some((v) => v.form === "base" && v.lemma === word)
      : kind === "participle"
        ? read.verbs.some((v) => v.form === "participle")
        : (!read.noun || objectNext) &&
          read.verbs.some((v) => v.form === "past" || v.form === "third" || v.form === "base");
}

// en.yaml rule en.adjectiveForAdverb def adverbFinding
export function adverbFinding(ctx: DetectContext, m: RegExpExecArray, adverb: string) {
  const start = m.indices!.groups!.target[0];
  const end = m.indices!.groups!.target[1];
  return finding("englishConfusedWords", "review_msg_adverb_form", start, end, [adverb], {
    context: enEvidence(ctx, m.index, end + 24),
  });
}

// en.yaml rule en.countNouns def COUNT_AMOUNT_UNITS
export const COUNT_AMOUNT_UNITS =
  /^(?:dollars|euros|pounds|cents|bucks|hours|minutes|seconds|days|weeks|months|years|miles|kilometers|kilometres|meters|metres|feet|inches|calories|degrees|percent)$/;

// en.yaml rule en.countNouns def COUNT_VOCATIVES
export const COUNT_VOCATIVES = /^(?:guys|folks|ladies|gentlemen|friends|kids|boys|girls)$/;

// en.yaml rule en.countNouns def COUNT_SINGULAR_S
export const COUNT_SINGULAR_S =
  /(?:ics|ness)$|^(?:news|means|series|species|thanks|odds|whereabouts|headquarters|lens|gas|bus|plus|bonus|status|campus|virus|census|corpus|focus|genius|sinus|surplus)$/;

// en.yaml rule en.countNouns def COUNT_CLAUSE_LINKS
export const COUNT_CLAUSE_LINKS = /^(?:after|before|since|until|than|then|ago|when|while)$/;

// en.yaml rule en.countNouns def COUNT_IRREGULAR_PLURALS
export const COUNT_IRREGULAR_PLURALS = /^(?:people|children|men|women|feet|teeth|mice|geese)$/;

// en.yaml rule en.countNouns def countPluralHead
export function countPluralHead(ctx: DetectContext, noun: string, end: number, verbNext: boolean) {
  const read = EN_FUNCTION_WORDS.has(noun) ? null : englishWordInfo(noun);
  const plural =
    COUNT_IRREGULAR_PLURALS.test(noun) ||
    (read ? read.plural && !read.adjective : enNounOnly(noun) === "plural");
  if (!(
    plural &&
    !COUNT_AMOUNT_UNITS.test(noun) &&
    !EN_MASS.has(noun) &&
    !COUNT_SINGULAR_S.test(noun)
  ))
    return false;
  const next = enTokensAfter(ctx, end, 1)[0];
  return (
    next?.kind !== "word" ||
    EN_FUNCTION_WORDS.has(next.lower) ||
    COUNT_CLAUSE_LINKS.test(next.lower) ||
    countHeadBefore(next.lower, verbNext)
  );
}

// en.yaml rule en.countNouns def countHeadBefore
export function countHeadBefore(word: string, verbNext: boolean) {
  const after = englishWordInfo(word);
  return (
    (verbNext && after?.verbs.some((v) => v.form !== "base" && v.form !== "ing") && !after.noun) ||
    !!after?.adverb ||
    (!after?.noun && !after?.verbs.length && !enNounOnly(word))
  );
}

// en.yaml rule en.countNouns def countCompound
export function countCompound(ctx: DetectContext, end: number) {
  const next = enTokensAfter(ctx, end, 1)[0];
  if (!(
    next?.kind === "word" &&
    !EN_FUNCTION_WORDS.has(next.lower) &&
    !COUNT_CLAUSE_LINKS.test(next.lower)
  ))
    return false;
  const read = englishWordInfo(next.lower);
  if (read?.verbs.some((v) => v.form === "third")) return false;
  return (
    !read ||
    !(read.noun || read.adjective || read.adverb || read.verbs.length) ||
    read.noun ||
    read.plural
  );
}

// en.yaml rule en.countNouns def countMuchPlural
export function countMuchPlural(
  ctx: DetectContext,
  m: RegExpExecArray,
  before: string,
  noun: string,
  end: number,
) {
  if (!(before !== "how" && enNounOnly(noun) === "plural" && !COUNT_VOCATIVES.test(noun)))
    return false;
  const next = enTokensAfter(ctx, end, 1)[0];
  if (next?.kind === "word" && !EN_PREPOSITIONS.has(next.lower)) return false;
  const clause = /[^.!?;:\n]*$/.exec(ctx.text.slice(Math.max(0, m.index - 80), m.index))![0];
  if (/\b(?:thanks?|love|miss|appreciate)\b/i.test(clause)) return false;
  return true;
}

// en.yaml rule en.doubleNegatives def NEGATION_CLAUSE_BREAK
export const NEGATION_CLAUSE_BREAK =
  /^(?:that|which|who|whom|whose|what|where|when|why|how|because|if|unless|but|and|or|so|than|as|while|until|whether|though|although|since|yet|nor|said|says|think|thought|know|knew|believe|believed|realize|realized|mean|meant)$/;

// en.yaml rule en.doubleNegatives def NEGATION_NO_PHRASES
export const NEGATION_NO_PHRASES =
  /^(?:one|longer|matter|more|less|doubt|further|sooner|way|thanks|end|wonder|problem|question|idea|less|other|sense|use)$/;

// en.yaml rule en.relativeAgreement def RS_SINGULAR_PRONOUNS
export const RS_SINGULAR_PRONOUNS =
  /^(?:he|she|something|anything|everything|nothing|someone|anyone|everyone|somebody|anybody|everybody)$/;

// en.yaml rule en.relativeAgreement def RS_NOT_ANTECEDENT
export const RS_NOT_ANTECEDENT =
  /^(?:none|one|two|three|four|five|six|seven|eight|nine|ten|dozen|hundred|thousand|million|handful|faculty|days?|weeks?|months?|years?|times?|hours?|minutes?|moments?|nights?|mornings?|evenings?|summer|winter|spring|autumn|fall|season|decades?|century|era|fact|idea|chances?|possibility|probability|likelihood|hope|belief|claim|notion|odds|risk|sign|proof|assumption|impression|feeling|rumou?r|suggestion|way)$/;

// en.yaml rule en.relativeAgreement def RS_CLEFT
export const RS_CLEFT = /\b(?:it|this|that)(?:['’]s|[ \t ]+(?:is|was))\b|\b(?:is|was)[ \t ]+it\b/i;

// en.yaml rule en.relativeAgreement def RS_VERB_EVIDENCE
export const RS_VERB_EVIDENCE =
  /^(?:the|a|an|my|your|his|her|our|their|its|this|these|those|it|them|me|us|him|you|every|each|any|some|all)$/;

// en.yaml rule en.relativeAgreement def RS_LINKING
export const RS_LINKING =
  /^(?:feel|look|sound|seem|taste|smell|appear|become|remain|stay|get|grow)$/;

// en.yaml rule en.relativeAgreement def RS_MODALS
export const RS_MODALS =
  /^(?:can|could|will|would|shall|should|may|might|must|need|dare|ought|be)$/;

// en.yaml rule en.relativeAgreement def RS_LATER_VERB
export const RS_LATER_VERB =
  /^(?:is|are|was|were|has|have|had|will|would|can|could|should|must|may|might|do|does|did)$/;

// en.yaml rule en.relativeAgreement def rsVerbLater
export function rsVerbLater(ctx: DetectContext, index: number) {
  const hit = enTokensAfter(ctx, index, 10).find(
    (t) => t.kind !== "word" || RS_LATER_VERB.test(t.lower),
  );
  return hit?.kind === "word";
}

// en.yaml rule en.relativeAgreement def rsAntecedent
export function rsAntecedent(
  ctx: DetectContext,
  word: string,
  index: number,
  pronoun: string,
): "singular" | "plural" | null {
  return RS_SINGULAR_PRONOUNS.test(word)
    ? "singular"
    : word === "those"
      ? "plural"
      : EN_FUNCTION_WORDS.has(word) || RS_NOT_ANTECEDENT.test(word) || EN_COLLECTIVE.has(word)
        ? null
        : rsClauseOwner(ctx, word, index, pronoun);
}

// en.yaml rule en.relativeAgreement def rsClauseOwner
export function rsClauseOwner(
  ctx: DetectContext,
  word: string,
  index: number,
  pronoun: string,
): "singular" | "plural" | null {
  const clause = /(?:[^.!?;:,()\n—]|[,;](?=[\dA-Za-z]))*$/.exec(
    ctx.text.slice(Math.max(0, index - 120), index),
  )![0];
  if (RS_CLEFT.test(clause) || /\b(?:that|which|who)\b/i.test(clause)) return null;
  const before = (clause.match(/[A-Za-z]+(?:[-'’][A-Za-z]+)*/g) ?? []).map((w) => w.toLowerCase());
  const stop = before
    .slice(-6)
    .reverse()
    .find(
      (w) =>
        EN_PREPOSITIONS.has(w) ||
        /^(?:to|amongst|among|like|than|given)$/.test(w) ||
        EN_AUXILIARIES.has(w) ||
        /n['’]t$/.test(w),
    );
  if (stop && (EN_PREPOSITIONS.has(stop) || /^(?:to|amongst|among|like|than|given)$/.test(stop)))
    return null;
  const previous = before.at(-1);
  if (pronoun === "that" && /^(?:so|such|now)$/.test(previous ?? "")) return null;
  if (previous === "please" || /^(?:stuff|junk|gear|crap|garbage|rubbish)$/.test(word)) return null;
  const read = englishWordInfo(word);
  if (!(
    !read?.verbs.length ||
    (!!previous && (EN_DETERMINERS.has(previous) || rsModifier(previous)))
  ))
    return null;
  const counted = enNounNumber(word)?.number;
  if (counted === "plural" && /^(?:a|an|every|each|one|another)$/.test(previous ?? "")) return null;
  return counted
    ? counted
    : !read?.noun || read.verbs.length || read.adjective || read.adverb
      ? null
      : read.plural
        ? "plural"
        : "singular";
}

// en.yaml rule en.relativeAgreement def rsModifier
export function rsModifier(word: string) {
  const read = englishWordInfo(word);
  return !!read && (read.adjective || read.verbs.length > 0);
}

// en.yaml rule en.relativeAgreement def rsSingularFix
export function rsSingularFix(
  ctx: DetectContext,
  at: number,
  noun: string,
  verb: string,
  evidenced: boolean,
) {
  if (
    /\b(?:and|or)\b(?:[ \t ]+[A-Za-z]+){0,3}[ \t ]*$/i.test(
      ctx.text.slice(Math.max(0, at - 40), at),
    ) ||
    (/[A-Za-z],[ \t ]*$/.test(ctx.text.slice(Math.max(0, at - 4), at)) &&
      !/^(?:some|any|every|no)(?:thing|one|body)$/.test(noun))
  )
    return null;
  if (EN_MASS.has(noun)) return null;
  const read = englishWordInfo(verb);
  const fixed =
    (verb === "do" || verb === "have") && !evidenced ? null : (RS_TO_SINGULAR[verb] ?? null);
  return (
    fixed ||
    (!RS_MODALS.test(verb) &&
    read?.verbs.some((v) => v.form === "base" && v.lemma === verb) &&
    !read.verbs.some((v) => v.form !== "base") &&
    !/^(?:please|thank)$/.test(verb) &&
    ((!read.noun && !read.plural && !read.adjective && !read.adverb) || evidenced)
      ? englishInflect(verb, "third")
      : null)
  );
}

// en.yaml rule en.relativeAgreement def rsIsName
export function rsIsName(word: string) {
  return /^[A-Z][a-z]+$/.test(word) && !englishWordInfo(word);
}

// en.yaml rule en.relativeAgreement def rsCapital
export function rsCapital(word: string) {
  return /^[A-Z][a-z]+$/.test(word) && !EN_FUNCTION_WORDS.has(word.toLowerCase());
}

// en.yaml rule en.relativeAgreement def rsNameSubject
export function rsNameSubject(
  ctx: DetectContext,
  start: number,
  end: number,
  typed: string,
  fix: string | null,
  from: number,
  rule: "englishSubjectVerbAgreement" | "englishPossibleErrors",
) {
  return fix && fix !== typed
    ? finding(rule, "review_msg_subject_verb", start, end, [fix], {
        context: enEvidence(ctx, from, end),
      })
    : null;
}

// en.yaml rule en.pronounForms def RS_CLAUSE_CUE
export const RS_CLAUSE_CUE =
  /^(?:so|because|when|whenever|while|since|until|although|though|if|unless|once|that|feel|hope|think|guess|believe|know|sure|wish|maybe|perhaps)$/;

// en.yaml rule en.pronounForms def rsThirdLemma
export function rsThirdLemma(ctx: DetectContext, m: RegExpExecArray, verb: string) {
  const read = englishWordInfo(verb);
  if (!read?.verbs.some((v) => v.form === "third")) return null;
  const object = enTokensAfter(ctx, m.index + m[0].length, 1)[0];
  if (
    (read.noun || read.plural) &&
    !(object?.kind === "word" && RS_VERB_EVIDENCE.test(object.lower))
  )
    return null;
  return englishLemma(verb, "third") ?? "";
}

// en.yaml rule en.pronounForms def rsPronounForm
export function rsPronounForm(
  ctx: DetectContext,
  start: number,
  end: number,
  typed: string,
  fix: string,
  from: number,
) {
  return finding(
    "englishPronounVerbWhitelistAgreement",
    "review_msg_pronoun_verb",
    start,
    end,
    [caseLike(typed, fix)],
    { context: enEvidence(ctx, from, end) },
  );
}

// en.yaml rule en.questionAuxiliaries def questionPastBare
export function questionPastBare(word: string) {
  const forms = englishVerbForms(word);
  if (forms && (forms.ambiguous.includes(word) || forms.lemma === word)) return null;
  return englishLemma(word, "past");
}

// en.yaml rule en.questionAuxiliaries def questionBareOf
export function questionBareOf(word: string): string | null {
  const read = englishWordInfo(word);
  if (!read?.verbs.length) return null;
  return word.endsWith("ing")
    ? englishLemma(word, "ing")
    : word.endsWith("s")
      ? englishLemma(word, "third")
      : !read.verbs.some((v) => v.form === "past")
        ? null
        : questionPastBare(word);
}

// en.yaml rule en.questionAuxiliaries def questionFinding
export function questionFinding(
  ctx: DetectContext,
  messageKey: RawFinding["messageKey"],
  start: number,
  end: number,
  alternatives: string[],
) {
  return finding("englishAuxiliaryBaseVerb", messageKey, start, end, alternatives, {
    ...(alternatives.length > 1 ? { requiresChoice: true as const } : {}),
    context: enEvidence(ctx, start, end),
  });
}

// en.yaml rule en.causativeThird def QUESTION_CAUSED
export const QUESTION_CAUSED =
  /^(?:works|happens|runs|seems|sounds|looks|fails|moves|stops|loads|starts|compiles|crashes|fits|appears|disappears|lasts|stays|loops|wonders|laughs|smiles|cries|thinks|feels|realizes|believes|wants|wishes|forgets|remembers|knows|understands)$/;

// en.yaml rule en.superlativeArticle def comparisonPlain
export function comparisonPlain(word: string, suffix: string): string | null {
  if (!word.endsWith(suffix)) return null;
  const read = englishWordInfo(word);
  if (!(read?.adjective && !read.noun)) return null;
  const stem = word.slice(0, -suffix.length);
  return (
    [
      stem,
      `${stem}e`,
      /i$/.test(stem) ? `${stem.slice(0, -1)}y` : "",
      /([b-df-hj-np-tv-z])\1$/.test(stem) ? stem.slice(0, -1) : "",
    ].find((c) => c.length > 2 && englishWordInfo(c)?.adjective) ?? null
  );
}

// en.yaml rule en.superlativeArticle def comparisonSuperlative
export function comparisonSuperlative(word: string) {
  return word === "best" || word === "worst" || !!comparisonPlain(word, "est");
}

// en.yaml rule en.superlativeArticle def COMPARISON_SET_PHRASES
export const COMPARISON_SET_PHRASES =
  /^(?:friends?|man|men|practices?|case|value|priority|quality|effort|seller|sellers|interests?|regards|wishes)$/;

// en.yaml rule en.collocations def collocationKnown
export function collocationKnown(token: EnToken | undefined) {
  return (
    token?.kind === "word" &&
    (EN_FUNCTION_WORDS.has(token.lower) ||
      !!englishWordInfo(token.lower) ||
      !!enListedNoun(token.lower))
  );
}

// en.yaml rule en.collocations def collocationNoInfinitive
export function collocationNoInfinitive(word: string) {
  const read = englishWordInfo(word);
  return !read?.verbs.some((v) => v.form === "base" && v.lemma === word) || !!read?.noun;
}

// en.yaml rule en.collocations def collocationObject
export function collocationObject(
  _ctx: DetectContext,
  _head: EnToken,
  after: readonly EnToken[],
): boolean {
  const next = after[1];
  return !next
    ? false
    : next.kind === "number"
      ? true
      : next.kind !== "word"
        ? false
        : EN_OBJECT_PRONOUNS.has(next.lower)
          ? true
          : EN_DETERMINERS.has(next.lower) || COLLOCATION_POSSESSIVES.has(next.lower)
            ? collocationKnown(after[2])
            : EN_FUNCTION_WORDS.has(next.lower) || !collocationKnown(next)
              ? false
              : collocationNoInfinitive(next.lower);
}

// en.yaml rule en.collocations def collocationPerson
export function collocationPerson(
  ctx: DetectContext,
  head: EnToken,
  after: readonly EnToken[],
): boolean {
  return (
    !!after[1] &&
    after[1].kind === "word" &&
    (/^(?:me|him|her|us|them|you|everyone|everybody|people)$/.test(after[1].lower) ||
      (COLLOCATION_POSSESSIVES.has(after[1].lower) && collocationObject(ctx, head, after)))
  );
}

// en.yaml rule en.collocations def collocationPronoun
export function collocationPronoun(
  _ctx: DetectContext,
  _head: EnToken,
  after: readonly EnToken[],
): boolean {
  return (
    !!after[1] &&
    /^(?:me|him|her|us|them|you|everyone|everybody|people|others)$/.test(after[1].lower)
  );
}

// en.yaml rule en.collocations def collocationAfterBe
export function collocationAfterBe(
  ctx: DetectContext,
  head: EnToken,
  after: readonly EnToken[],
): boolean {
  return (
    EN_BE_FINITE.has(enWordBefore(ctx, head.start)) &&
    collocationObject(ctx, head, after) &&
    !/ing$/.test(after[1].lower)
  );
}

// en.yaml rule en.collocations def collocationSimilarWith
export function collocationSimilarWith(
  ctx: DetectContext,
  head: EnToken,
  after: readonly EnToken[],
): boolean {
  return (
    collocationObject(ctx, head, after) &&
    (!after[1] || !/^(?:respect|regard)$/.test(after[1].lower))
  );
}

// en.yaml rule en.collocations def collocationSimilarAs
export function collocationSimilarAs(
  ctx: DetectContext,
  head: EnToken,
  after: readonly EnToken[],
): boolean {
  return (
    collocationObject(ctx, head, after) &&
    !/^(?:as|so|how|too)$/.test(enWordBefore(ctx, head.start))
  );
}

// en.yaml rule en.collocations def collocationFarOf
export function collocationFarOf(
  ctx: DetectContext,
  head: EnToken,
  after: readonly EnToken[],
): boolean {
  return (
    collocationObject(ctx, head, after) &&
    (!after[1] || !/^(?:a|an)$/.test(after[1].lower)) &&
    !/^(?:so|thus|as|how|too)$/.test(enWordBefore(ctx, head.start))
  );
}

// en.yaml rule en.collocations def collocationMarriedWith
export function collocationMarriedWith(
  ctx: DetectContext,
  head: EnToken,
  after: readonly EnToken[],
): boolean {
  return (
    collocationSpouse(ctx, head, after) &&
    /^(?:get|gets|got|getting|be|been|being|is|are|was|were|am)$/.test(
      enWordBefore(ctx, head.start),
    )
  );
}

// en.yaml rule en.collocations def collocationMarryWith
export function collocationMarryWith(
  ctx: DetectContext,
  head: EnToken,
  after: readonly EnToken[],
): boolean {
  return (
    collocationSpouse(ctx, head, after) &&
    !/^(?:get|gets|got|getting|be|been|being|is|are|was|were|am|happily|newly|recently|once|still|just|now|not)$/.test(
      enWordBefore(ctx, head.start),
    )
  );
}

// en.yaml rule en.collocations def collocationInvestOn
export function collocationInvestOn(
  ctx: DetectContext,
  head: EnToken,
  after: readonly EnToken[],
): boolean {
  return collocationObject(ctx, head, after) && (!after[1] || !/^behalf$/.test(after[1].lower));
}

// en.yaml rule en.collocations def collocationSufferingOf
export function collocationSufferingOf(
  ctx: DetectContext,
  head: EnToken,
  after: readonly EnToken[],
): boolean {
  return collocationObject(ctx, head, after) && COLLOCATION_BE.has(enWordBefore(ctx, head.start));
}

// en.yaml rule en.collocations def collocationVerbObject
export function collocationVerbObject(
  ctx: DetectContext,
  head: EnToken,
  after: readonly EnToken[],
): boolean {
  return collocationObject(ctx, head, after) && collocationVerbSlot(ctx, head);
}

// en.yaml rule en.collocations def collocationDiscuss
export function collocationDiscuss(
  ctx: DetectContext,
  head: EnToken,
  after: readonly EnToken[],
): boolean {
  return (
    collocationObject(ctx, head, after) &&
    !/\n[ \t]*$/.test(ctx.text.slice(Math.max(0, head.start - 8), head.start))
  );
}

// en.yaml rule en.collocations def collocationVerbSlot
export function collocationVerbSlot(ctx: DetectContext, head: EnToken) {
  const before = enWordBefore(ctx, head.start);
  return (
    EN_SUBJECT_PRONOUNS.has(before) ||
    /^(?:to|will|would|can|could|should|may|might|must|do|does|did|don['’]t|doesn['’]t|didn['’]t|please|also|still|really|often|never|always|just|people|many|most|some|kids|children|users)$/.test(
      before,
    )
  );
}

// en.yaml rule en.collocations def COLLOCATION_IDIOM
export const COLLOCATION_IDIOM = {
  of: /^course$/,
  at: /^(?:first|last|least|all|once|times|present|home|work|night|the (?:time|moment|start|end|same)|this (?:point|stage|time)|that (?:point|stage|time))$/,
  on: /^(?:average|and|top|time|purpose|occasion|behalf|board|paper|balance|the (?:day|whole|other|one|spot|way|weekend)|that (?:day|night|occasion)|this (?:day|occasion)|monday|tuesday|wednesday|thursday|friday|saturday|sunday)$/,
  from: /^(?:the (?:start|beginning|outset|get|first)|time|then|now|scratch|birth|childhood|day)$/,
  with: /^(?:no|respect|regard|time|age)$/,
  to: /^(?:date|this (?:day|point))$/,
  about:
    /^(?:time|it|half|[0-9][0-9.,]*|one|two|three|four|five|six|seven|eight|nine|ten|twenty|thirty|forty|fifty|a (?:dozen|hundred|thousand|million|few|couple|third|quarter|week|month|year)|an hour)$/,
  for: /^(?:now|sure|example|instance|good|once|ages|years|hours|days|weeks|months|a (?:while|moment|minute|second|bit|time|long)|the (?:first|second|third|last|next|moment|most|time))$/,
} as Record<string, RegExp>;

// en.yaml rule en.collocations def collocationIdiom
export function collocationIdiom(prep: EnToken, after: readonly EnToken[]) {
  const pattern = COLLOCATION_IDIOM[prep.lower];
  const one = after[1]?.lower ?? "";
  return !!pattern && (pattern.test(one) || pattern.test(`${one} ${after[2]?.lower ?? ""}`));
}

// en.yaml rule en.collocations def collocationSpouse
export function collocationSpouse(
  ctx: DetectContext,
  head: EnToken,
  after: readonly EnToken[],
): boolean {
  return (
    !!after[1] &&
    after[1].kind === "word" &&
    (collocationPerson(ctx, head, after) || /^(?:a|an|the)$/.test(after[1].lower)) &&
    !/^(?:children|kids|no|two|three|four|five|several|many)$/.test(after[1].lower) &&
    !/^[^.!?;\n]{0,40}?(?:child|children|kids?|bab(?:y|ies)|family|daughters?|sons?|twins|year-old|years? old|dog|cat)\b/i.test(
      ctx.text.slice(after[1].start, after[1].start + 48),
    )
  );
}

// en.yaml rule en.collocations def collocationBareNoun
export function collocationBareNoun(
  _ctx: DetectContext,
  _head: EnToken,
  after: readonly EnToken[],
): boolean {
  const next = after[1];
  return (
    next?.kind === "word" &&
    !EN_FUNCTION_WORDS.has(next.lower) &&
    !!englishWordInfo(next.lower)?.noun &&
    !englishWordInfo(next.lower)?.verbs.some((v) => v.form === "base")
  );
}

