export const YOU_COLLECTIVE =
  /^(?:team|family|staff|crew|class|group|company|band|club|department)$/;

// en.yaml rule en.slotConfusions def asciiWordAfter
export function asciiWordAfter(ctx: DetectContext, end: number) {
  return /^[ \t]{1,8}([A-Za-z]+(?:['’][a-z]+)?)/.exec(ctx.text.slice(end, end + 40))?.[1] ?? "";
}

// en.yaml rule en.slotConfusions def notAfterClauseVerb
export function notAfterClauseVerb(ctx: DetectContext, at: number) {
  const before = /([A-Za-z]+)[ \t\u00a0]+$/.exec(ctx.text.slice(Math.max(0, at - 24), at))?.[1];
  return !before || !YOU_CLAUSE_VERBS.test(before.toLowerCase());
}

// en.yaml rule en.slotConfusions def yourNoun
export function yourNoun(
  ctx: DetectContext,
  at: number,
  adj: string | undefined,
  noun: string,
  strict: boolean,
  listed: boolean,
) {
  if (!(noun === noun.toLowerCase() && !ADDRESSED.test(noun) && !ctx.dictionary.has(noun)))
    return false;
  if (!adj && /^(?:might|may|can|must)$/.test(noun)) return false;
  const adjective = typoInfo(adj);
  if (!(
    !adj || !(!adjective?.adjective || adjective.verbs.length || /^(?:own|only|alone)$/i.test(adj))
  ))
    return false;
  const read = typoInfo(noun);
  return (!read && (listed || !strict) && enListedNoun(noun) === "singular") ||
    !(
      !read?.noun ||
      read.plural ||
      read.adjective ||
      read.adverb ||
      (strict && read.verbs.some((v) => v.form === "base"))
    )
    ? notAfterClauseVerb(ctx, at)
    : false;
}

// en.yaml rule en.slotConfusions def youReadings
export function youReadings(
  m: RegExpExecArray,
): [string | undefined, string, string | undefined][] {
  return [
    [undefined, m.groups!.w1, m.groups!.w2],
    [m.groups!.w1, m.groups!.w2, m.groups!.w3],
  ];
}

// en.yaml rule en.slotConfusions def youVerbBase
export function youVerbBase(word: string | undefined) {
  return (
    word === "be" ||
    (!!word && !!typoInfo(word)?.verbs.some((v) => v.form === "base") && !typoInfo(word)!.plural)
  );
}

// en.yaml rule en.slotConfusions def participleAfterS
export function participleAfterS(m: RegExpExecArray) {
  const next = /^[ \t\u00a0]+([a-z]+)/.exec(
    m[0].slice(m.groups!.subject.length + m.groups!.verb.length),
  )?.[1];
  const read = next ? englishWordInfo(next) : null;
  return !!read?.verbs.some((v) => v.form === "participle") && !read.adjective;
}

// en.yaml rule en.slotConfusions def lexiconTag
export function lexiconTag(word: string, single: boolean): string | null {
  const read = englishWordInfo(word);
  if (!(!!read?.verbs.length && !EN_FUNCTION_WORDS.has(word))) return null;
  const forms = new Set(read.verbs.map((v) => v.form));
  return forms.has("past") && !forms.has("base")
    ? "didn't"
    : (single ? forms.has("third") : forms.has("base") && !forms.has("third"))
      ? single
        ? "doesn't"
        : "don't"
      : null;
}

// en.yaml rule en.slotConfusions def questionTag
export function questionTag(m: RegExpExecArray, word: string, single: boolean): string | null {
  return word === "'m" || word === "am" || word === "'re" || word === "are"
    ? "aren't"
    : word === "'s" || word === "is"
      ? word === "'s" && participleAfterS(m)
        ? null
        : "isn't"
      : word === "was"
        ? "wasn't"
        : word === "were"
          ? "weren't"
          : lexiconTag(word, single);
}

// en.yaml rule en.slotConfusions def bearForm
export function bearForm(ctx: DetectContext, typed: string, at: number) {
  const perfect = /\b(?:has|have|had)[ \t]+$/i.test(ctx.text.slice(Math.max(0, at - 8), at));
  return (
    { bares: "bears", baring: "bearing", bared: perfect ? "borne" : "bore" } as Record<
      string,
      string
    >
  )[typed];
}

// en.yaml rule en.britishUsage def britishBoot
export function britishBoot(m: RegExpExecArray, ctx: DetectContext) {
  if (/\bboots?\b/i.test(ctx.text.slice(Math.max(0, m.index - 120), m.index + m[0].length + 120)))
    return null;
  return m.groups!.target.toLowerCase() === "trunks" ? "boots" : "boot";
}

// en.yaml rule en.clauseConfusions def clauseFinding
export function clauseFinding(
  ctx: DetectContext,
  m: RegExpExecArray,
  ruleId: RawFinding["ruleId"],
  messageKey: RawFinding["messageKey"],
  alternatives: string[],
) {
  const start = m.indices!.groups!.target[0];
  const end = m.indices!.groups!.target[1];
  const typed = ctx.source.slice(start, end);
  return {
    ruleId,
    messageKey,
    range: { start, end },
    alternatives: alternatives.map((a) => caseLike(typed, a)),
    ...(alternatives.length > 1 ? { requiresChoice: true as const } : {}),
    context: enEvidence(ctx, m.index, end),
  };
}

// en.yaml rule en.clauseConfusions def CLAUSE_INFINITIVE_HEADS
export const CLAUSE_INFINITIVE_HEADS =
  /^(?:want|wants|wanted|need|needs|needed|like|would|try|tries|tried|trying|have|has|had|going|able|decided|decide|plan|plans|planned|hope|hoped|forgot|remember|wish|wished|must|should|will|can|could)$/;

// en.yaml rule en.clauseConfusions def CLAUSE_NOT_OWNED
export const CLAUSE_NOT_OWNED =
  /^(?:is|are|was|were|be|been|being|will|would|can|could|should|may|might|must|has|have|had|and|or|but|so|yet|too|again|now|then|today|tomorrow|yesterday|tonight|somewhere|anywhere|everywhere|nowhere|instead|either|though|first|already|once|ever|soon|also|alone|together|until|later|before|after|right|over)$/;

// en.yaml rule en.clauseConfusions def CLAUSE_EVALUATIVE
export const CLAUSE_EVALUATIVE =
  /^(?:great|good|fine|right|wrong|cool|fun|perfect|better|worse|ok|okay)$/;

// en.yaml rule en.clauseConfusions def clausePredicateAdjective
export function clausePredicateAdjective(word: string) {
  const read = englishWordInfo(word);
  return (
    CLAUSE_EVALUATIVE.test(word) ||
    (!!read?.adjective && !read.noun && !read.verbs.length && !EN_FUNCTION_WORDS.has(word))
  );
}

// en.yaml rule en.neighbourSlots def typoInfo
export function typoInfo(word: string | undefined) {
  return word ? englishWordInfo(word.toLowerCase()) : null;
}

// en.yaml rule en.neighbourSlots def typoAdjective
export function typoAdjective(word: string) {
  return !!typoInfo(word)?.adjective && !EN_FUNCTION_WORDS.has(word);
}

// en.yaml rule en.neighbourSlots def typoVerbForm
export function typoVerbForm(word: string, form: string) {
  return !!typoInfo(word)?.verbs.some((v) => v.form === form);
}

// en.yaml rule en.prepositionSlots def PREPOSITION_MONTHS
export const PREPOSITION_MONTHS =
  /^(?:January|February|March|April|May|June|July|August|September|October|November|December|Monday|Tuesday|Wednesday|Thursday|Friday|Saturday|Sunday)$/;

// en.yaml rule en.prepositionSlots def prepositionIng
export function prepositionIng(word: string) {
  return !!englishWordInfo(word.toLowerCase())?.verbs.some((v) => v.form === "ing");
}

// en.yaml rule en.clauseFrames def CLAUSE_VERB_LIKE
export const CLAUSE_VERB_LIKE = /\b(?!(?:he|she|it|they|we|you|i)\b)[a-z]+[ \t ]{1,8}like\b/i;

// en.yaml rule en.clauseFrames def CLAUSE_PRONOUN_LIKE
export const CLAUSE_PRONOUN_LIKE = /\b(?:he|she|it|they|we|you|i)[ \t ]{1,8}like\b/i;

// en.yaml rule en.clauseFrames def clauseEllipsis
export function clauseEllipsis(ctx: DetectContext, m: RegExpExecArray) {
  const end = m.index + m[0].length;
  const before = ctx.text.slice(Math.max(0, m.index - 160), m.index);
  return (
    CLAUSE_VERB_LIKE.test(before) ||
    (!/^(?:me|you|him|her|us|them|it)$/i.test(m[0].split(/\s+/).at(-1)!) &&
      CLAUSE_PRONOUN_LIKE.test(
        `${/[^.!?\n]*$/.exec(before)![0]} ${/^[^.!?\n]*/.exec(ctx.text.slice(end, end + 160))![0]}`,
      ))
  );
}

// en.yaml rule en.clauseFrames def clauseLikedNoun
export function clauseLikedNoun(ctx: DetectContext, m: RegExpExecArray) {
  const who = m.groups!.who;
  const noun = m.groups!.noun;
  if (who.toLowerCase() === "it" || noun !== noun.toLowerCase() || CLAUSE_NOT_LIKED.has(noun))
    return false;
  const r = enInfo(noun);
  if (!r?.noun || r.adjective || r.adverb || r.verbs.some((v) => v.form !== "third")) return false;
  const after = enTokensAfter(ctx, m.index + m[0].length, 1)[0];
  return (
    after.kind !== "word" ||
    (!EN_AUXILIARIES.has(after.lower) &&
      !enInfo(after.lower)?.verbs.some((v) => v.form === "third" || v.form === "past"))
  );
}

// en.yaml rule en.slipFrames def SLIP_TOO_DEGREE
export const SLIP_TOO_DEGREE =
  /^(?:fast|soon|late|early|slowly|quickly|much|many|long|far|big|small|hard|easy|busy|tired|young|old|expensive|cheap|close|high|low|loud|hot|cold)$/;

// en.yaml rule en.slipFrames def SLIP_MOTION
